/**
 * E2E test: creates a test customer, funds the wallet, orders a VPS
 * (same DB operations the orderServer action performs), then waits for
 * the worker to provision it and prints connection details.
 */
import { PrismaClient } from "@prisma/client";
import bcrypt from "bcryptjs";

const db = new PrismaClient();

async function main() {
  const email = "e2e-test@nxeon.local";
  let user = await db.user.findUnique({ where: { email } });
  if (!user) {
    user = await db.user.create({
      data: {
        email,
        name: "E2E Test",
        passwordHash: await bcrypt.hash("e2e-test-password", 12),
        balanceCents: 1000,
      },
    });
  }

  const plan = await db.plan.findUnique({ where: { slug: "nano" } });
  const os = await db.osTemplate.findUnique({ where: { slug: "ubuntu-24-04" } });
  if (!plan || !os) throw new Error("seed data missing");

  const server = await db.$transaction(async (tx) => {
    await tx.user.update({ where: { id: user!.id }, data: { balanceCents: { decrement: plan.priceCents } } });
    await tx.walletTransaction.create({
      data: { userId: user!.id, amountCents: -plan.priceCents, description: "E2E order" },
    });
    // Server.hostname is globally unique (see its schema comment) — re-running
    // this script against a non-empty DB used to insert a second row literally
    // named "e2e-test" every time; now that the constraint exists, that would
    // just throw. A short random suffix per run keeps this script repeatable
    // without needing its own collision-check query.
    const hostname = `e2e-test-${Math.random().toString(36).slice(2, 8)}`;
    const s = await tx.server.create({
      data: {
        name: hostname,
        hostname,
        userId: user!.id,
        planId: plan.id,
        osTemplateId: os.id,
        expiresAt: new Date(Date.now() + 30 * 86400_000),
      },
    });
    await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
    return s;
  });

  console.log(`ordered server ${server.id}, waiting for worker...`);
  const deadline = Date.now() + 10 * 60_000;
  for (;;) {
    const s = await db.server.findUnique({ where: { id: server.id } });
    if (!s) throw new Error("server vanished");
    process.stdout.write(`  status=${s.status} vmid=${s.vmid ?? "-"}\r`);
    if (s.status === "RUNNING") {
      console.log(`\nRESULT ip=${s.ipAddress} sshPort=${s.sshPort} password=${s.rootPassword} vmid=${s.vmid}`);
      break;
    }
    if (s.status === "ERROR") {
      const job = await db.job.findFirst({ where: { serverId: s.id }, orderBy: { createdAt: "desc" } });
      throw new Error(`provisioning failed: ${job?.error}`);
    }
    if (Date.now() > deadline) throw new Error("timeout");
    await new Promise((r) => setTimeout(r, 5000));
  }
}

main().finally(() => db.$disconnect());

1	// Throwaway screenshot capture for blog imagery.
2	// Captures polished public showcase UI from https://nxeon.cloud into
3	// public/blog/screenshots/*.png. CAPTURE-ONLY — no deploy/prisma/restart.
4	//
5	//   node scripts/capture-screens.mjs
6	//
7	import { chromium } from "playwright";
8	import { mkdirSync, statSync, existsSync, unlinkSync } from "node:fs";
9	import { fileURLToPath } from "node:url";
10	import { dirname, join } from "node:path";
11	
12	const ROOT = dirname(dirname(fileURLToPath(import.meta.url)));
13	const OUT = join(ROOT, "public", "blog", "screenshots");
14	const BASE = process.env.BASE_URL || "https://nxeon.cloud";
15	mkdirSync(OUT, { recursive: true });
16	
17	const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
18	
19	// ScreenFrame showcase components — captured as element screenshots by the
20	// exact header title text (anchored to the .rounded-2xl app-window root).
21	const FRAMES = [
22	  { file: "server-dashboard.png",       url: "/",              title: "web-prod-01 · sgp1" },
23	  { file: "mail-inbox.png",             url: "/",              title: "you@yourbrand.com" },
24	  { file: "dns-manager.png",            url: "/",              title: "DNS · yourbrand.com" },
25	  { file: "migration-center.png",       url: "/",              title: "Nxeon · Migration" },
26	  { file: "game-servers.png",           url: "/game-servers",  title: "Minecraft · survival-smp" },
27	  { file: "block-storage-volumes.png",  url: "/block-storage", title: "Volumes" },
28	  { file: "ai-builder.png",             url: "/features",      title: "Claude · connected to web-prod-01" },
29	];
30	
31	// Non-frame element captures via CSS selector.
32	const SELECTORS = [
33	  { file: "deploy-wizard.png",    url: "/",                       sel: ".glass.rounded-2xl" },
34	  { file: "pricing-plans.png",    url: "/pricing",                sel: "div.grid.xl\\:grid-cols-4" },
35	  { file: "blog-index.png",       url: "/blog",                   sel: "div.grid.lg\\:grid-cols-3", maxH: 1120 },
36	  { file: "domain-generator.png", url: "/tools/domain-generator", sel: "section.relative .card" },
37	  { file: "free-tools.png",       url: "/tools",                  sel: "div.grid.lg\\:grid-cols-3.mt-10" },
38	];
39	
40	const results = [];
41	
42	async function settle(page, url) {
43	  await page.goto(BASE + url, { waitUntil: "networkidle", timeout: 60000 }).catch(() => {});
44	  await page.evaluate(() => window.scrollTo(0, 0));
45	  await sleep(700);
46	}
47	
48	async function shoot(loc, file, maxH) {
49	  const path = join(OUT, file);
50	  await loc.scrollIntoViewIfNeeded({ timeout: 8000 });
51	  await sleep(1100); // Reveal opacity/transform + bar animations settle
52	  if (maxH) {
53	    // Cap very tall page sections: clip to the top maxH CSS px of the element.
54	    const box = await loc.boundingBox();
55	    if (box && box.height > maxH) {
56	      await loc.page().screenshot({
57	        path,
58	        clip: { x: box.x, y: box.y, width: box.width, height: maxH },
59	      });
60	    } else {
61	      await loc.screenshot({ path });
62	    }
63	  } else {
64	    await loc.screenshot({ path });
65	  }
66	  const kb = statSync(path).size / 1024;
67	  const ok = kb > 15;
68	  if (!ok && existsSync(path)) unlinkSync(path);
69	  results.push({ file, ok, kb: Math.round(kb) });
70	  console.log(`${ok ? "OK " : "BAD"}  ${file.padEnd(28)} ${Math.round(kb)}KB`);
71	  return ok;
72	}
73	
74	const run = async () => {
75	  const browser = await chromium.launch();
76	  const ctx = await browser.newContext({
77	    viewport: { width: 1440, height: 900 },
78	    deviceScaleFactor: 2,
79	    reducedMotion: "reduce", // rest looping mocks on a clean, deterministic frame
80	  });
81	  // Pre-record cookie consent so the bottom banner never overlaps captures.
82	  await ctx.addCookies([
83	    { name: "nxeon_cookie_consent", value: "necessary", domain: new URL(BASE).hostname, path: "/" },
84	  ]);
85	  const page = await ctx.newPage();
86	
87	  for (const t of FRAMES) {
88	    try {
89	      await settle(page, t.url);
90	      const loc = page
91	        .locator("div.rounded-2xl")
92	        .filter({ has: page.locator(".truncate", { hasText: t.title }) })
93	        .first();
94	      await loc.waitFor({ state: "visible", timeout: 15000 });
95	      await shoot(loc, t.file);
96	    } catch (e) {
97	      console.log(`ERR  ${t.file}: ${e.message.split("\n")[0]}`);
98	      results.push({ file: t.file, ok: false, kb: 0 });
99	    }
100	  }
101	
102	  for (const t of SELECTORS) {
103	    try {
104	      await settle(page, t.url);
105	      const loc = page.locator(t.sel).first();
106	      await loc.waitFor({ state: "visible", timeout: 15000 });
107	      await shoot(loc, t.file, t.maxH);
108	    } catch (e) {
109	      console.log(`ERR  ${t.file}: ${e.message.split("\n")[0]}`);
110	      results.push({ file: t.file, ok: false, kb: 0 });
111	    }
112	  }
113	
114	  await browser.close();
115	  const good = results.filter((r) => r.ok);
116	  console.log(`\n=== ${good.length}/${results.length} captured ===`);
117	  console.log(good.map((r) => "/blog/screenshots/" + r.file).join("\n"));
118	};
119	
120	run().catch((e) => {
121	  console.error(e);
122	  process.exit(1);
123	});
124

1	/**
2	 * Refuse to write to a database nobody deliberately pointed us at.
3	 *
4	 * ---------------------------------------------------------------------------
5	 * THE INCIDENT THIS EXISTS FOR (2026-07-26)
6	 * ---------------------------------------------------------------------------
7	 * An agent ran `prisma/seed.ts` from a scratch working tree. That tree had its
8	 * `node_modules` SYMLINKED to /opt/nxeon/node_modules, so `@prisma/client`
9	 * resolved through the symlink, and Prisma's dotenv loader walked up from the
10	 * REAL module location and loaded `/opt/nxeon/.env` — the PRODUCTION env. The
11	 * seed therefore connected to the production database `nxeon` while every human
12	 * signal (the cwd, the checkout, the intent) said "scratch".
13	 *
14	 * It happened to be a pure `upsert` seed, so it did no damage. That is luck, not
15	 * a control. The same accident with `prisma db push --accept-data-loss`, or with
16	 * a seed that had grown a `deleteMany`, destroys a live hosting platform's
17	 * customer records.
18	 *
19	 * The root cause is NOT "the seed was careless". It is that a writing script
20	 * inherits its target from ambient environment resolution — a mechanism with no
21	 * confirmation step, which resolves silently and can be wrong for reasons that
22	 * are invisible at the call site (a symlink three directories away).
23	 *
24	 * ---------------------------------------------------------------------------
25	 * THE CONTROL
26	 * ---------------------------------------------------------------------------
27	 * A writing script must state, out loud, which database it believes it is about
28	 * to write to. The operator states it independently, via `NXEON_DB_TARGET`. The
29	 * script runs only if the two agree.
30	 *
31	 *     NXEON_DB_TARGET=nxeon_staging npx tsx prisma/seed.ts
32	 *
33	 * This is deliberately NOT a "--force"/"--yes" flag. A blanket confirmation
34	 * answers "do you want to proceed?", and in the incident above the honest answer
35	 * was yes — the operator did want to seed, just not THAT database. Naming the
36	 * target answers the question that was actually wrong. An operator who types
37	 * `NXEON_DB_TARGET=nxeon_scratch` while the environment silently resolves to
38	 * `nxeon` gets a refusal and a diff, which is exactly the moment the symlink
39	 * becomes visible.
40	 *
41	 * Pure and side-effect free so it can be unit-tested without a database; see
42	 * test/db-target-guard.test.ts.
43	 */
44	
45	/** Environment variable through which the operator names the intended database. */
46	export const TARGET_ENV_VAR = "NXEON_DB_TARGET";
47	
48	export type DbTargetDecision =
49	  | { allowed: true; database: string }
50	  | { allowed: false; database: string | null; message: string };
51	
52	/**
53	 * Extract the database NAME from a PostgreSQL connection URL.
54	 *
55	 * Returns null when the URL is absent, unparseable, or names no database. We do
56	 * not guess: a connection string we cannot read is a connection string we cannot
57	 * confirm, and the whole point here is to stop acting on unconfirmed targets.
58	 */
59	export function databaseNameFromUrl(url: string | undefined | null): string | null {
60	  if (!url) return null;
61	  let parsed: URL;
62	  try {
63	    parsed = new URL(url);
64	  } catch {
65	    return null;
66	  }
67	  if (!/^postgres(ql)?:$/.test(parsed.protocol)) return null;
68	  // pathname is "/dbname" (or "" / "/" when no database is named).
69	  const raw = parsed.pathname.replace(/^\//, "");
70	  if (!raw) return null;
71	  let name: string;
72	  try {
73	    name = decodeURIComponent(raw);
74	  } catch {
75	    // A malformed percent-escape means we cannot say what database this is.
76	    return null;
77	  }
78	  return name || null;
79	}
80	
81	/**
82	 * Decide whether a writing script may proceed.
83	 *
84	 * `declared` is what the operator said (NXEON_DB_TARGET); `databaseUrl` is what
85	 * the environment silently resolved to. They must agree.
86	 */
87	export function decideDbTarget(opts: {
88	  databaseUrl: string | undefined | null;
89	  declared: string | undefined | null;
90	  /** Script name, used only to make the refusal message copy-pasteable. */
91	  script: string;
92	}): DbTargetDecision {
93	  const { databaseUrl, declared, script } = opts;
94	  const resolved = databaseNameFromUrl(databaseUrl);
95	
96	  if (!databaseUrl) {
97	    return {
98	      allowed: false,
99	      database: null,
100	      message:
101	        `Refusing to run ${script}: DATABASE_URL is not set.\n` +
102	        `Nothing was written. Set DATABASE_URL and ${TARGET_ENV_VAR} to the same database.`,
103	    };
104	  }
105	
106	  if (!resolved) {
107	    return {
108	      allowed: false,
109	      database: null,
110	      message:
111	        `Refusing to run ${script}: DATABASE_URL does not name a PostgreSQL database.\n` +
112	        `Nothing was written. Could not determine a database name from the connection string,\n` +
113	        `so there is no target to confirm against ${TARGET_ENV_VAR}.`,
114	    };
115	  }
116	
117	  const want = (declared ?? "").trim();
118	  if (!want) {
119	    return {
120	      allowed: false,
121	      database: resolved,
122	      message:
123	        `Refusing to run ${script}: ${TARGET_ENV_VAR} is not set.\n` +
124	        `Nothing was written.\n\n` +
125	        `This environment resolves to the database: ${resolved}\n\n` +
126	        `If that is genuinely the database you meant to write to, say so explicitly:\n` +
127	        `    ${TARGET_ENV_VAR}=${resolved} <your command>\n\n` +
128	        `Check it first. DATABASE_URL is resolved from a .env file that dotenv finds by\n` +
129	        `walking up from the Prisma client's REAL location — which, if node_modules is a\n` +
130	        `symlink, is not the tree you are standing in.`,
131	    };
132	  }
133	
134	  if (want !== resolved) {
135	    return {
136	      allowed: false,
137	      database: resolved,
138	      message:
139	        `Refusing to run ${script}: the database does not match what you asked for.\n` +
140	        `Nothing was written.\n\n` +
141	        `  ${TARGET_ENV_VAR} (what you asked for)  : ${want}\n` +
142	        `  DATABASE_URL    (what it resolved to): ${resolved}\n\n` +
143	        `These disagree, so one of them is wrong and it is not safe to guess which.\n` +
144	        `The usual cause is a .env being picked up from a different tree than the one you\n` +
145	        `are working in (a symlinked node_modules will do it). Confirm with:\n` +
146	        `    node -e 'console.log(process.env.DATABASE_URL)'`,
147	    };
148	  }
149	
150	  return { allowed: true, database: resolved };
151	}
152	
153	/**
154	 * Enforce the decision, or exit non-zero having written nothing.
155	 *
156	 * Exits rather than throwing: a throw from a top-level `main()` that lacks a
157	 * `.catch` becomes an unhandled rejection, which prints a stack trace and buries
158	 * the one sentence the operator needs to read.
159	 */
160	export function assertDbTarget(script: string): string {
161	  const decision = decideDbTarget({
162	    databaseUrl: process.env.DATABASE_URL,
163	    declared: process.env[TARGET_ENV_VAR],
164	    script,
165	  });
166	  if (!decision.allowed) {
167	    console.error(`\n${decision.message}\n`);
168	    process.exit(1);
169	  }
170	  console.log(`[${script}] target database confirmed: ${decision.database}`);
171	  return decision.database;
172	}
