// Throwaway, uncommitted: reset the known-existing staging demo account
// (demo@nxeon.cloud) to a known password + confirm verification/heardAboutUs
// state, for real Playwright screenshot capture of the customer portal.
// NOT for prod. Guarded by db-target-guard (see that file for why).
import { PrismaClient } from "@prisma/client";
import bcrypt from "bcryptjs";
import { assertDbTarget } from "./db-target-guard";

const db = new PrismaClient();

async function main() {
  assertDbTarget("_tmp-reset-demo-account.ts");
  const email = "demo@nxeon.cloud";
  const password = "NxeonDemo!2026";
  const user = await db.user.findUnique({ where: { email } });
  if (!user) throw new Error("expected existing demo@nxeon.cloud to be present");
  const updated = await db.user.update({
    where: { email },
    data: {
      passwordHash: await bcrypt.hash(password, 12),
      suspended: false,
      totpEnabled: false,
      emailVerifiedAt: user.emailVerifiedAt ?? new Date(),
      heardAboutUs: user.heardAboutUs || "skipped",
      excludeFromRevenue: true,
    },
  });
  console.log(JSON.stringify({ id: updated.id, email: updated.email, password, balanceCents: updated.balanceCents }));
}

main().finally(() => db.$disconnect());

