// Throwaway recon script — NOT committed. Logs in as the staging demo
// account and dumps DOM structure of key pages so a full capture script
// can be written with accurate selectors.
import { chromium } from "playwright";

const BASE = "https://staging.nxeon.cloud";
const EMAIL = "demo@nxeon.cloud";
const PASSWORD = "NxeonDemo!2026";

async function dismissInterstitials(page) {
  const selectors = [
    'button:has-text("Skip")',
    'button:has-text("Got it")',
    'button:has-text("No thanks")',
    'button.promo-modal-close',
    'button.promo-bar-close',
    '[aria-label="Close"]',
    '[aria-label="Dismiss"]',
  ];
  for (let i = 0; i < 3; i++) {
    let clicked = false;
    for (const sel of selectors) {
      try {
        const loc = page.locator(sel).first();
        if (await loc.isVisible({ timeout: 500 }).catch(() => false)) {
          await loc.click({ force: true, timeout: 2000 }).catch(() => {});
          clicked = true;
          await page.waitForTimeout(300);
        }
      } catch {}
    }
    if (!clicked) break;
  }
}

const run = async () => {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  await ctx.addCookies([
    { name: "nxeon_cookie_consent", value: "necessary", domain: "staging.nxeon.cloud", path: "/" },
  ]);
  const page = await ctx.newPage();

  console.log("=== LOGIN PAGE ===");
  await page.goto(BASE + "/login", { waitUntil: "networkidle", timeout: 30000 });
  await dismissInterstitials(page);
  await page.fill("#login-email", EMAIL);
  await page.fill("#login-password", PASSWORD);
  await page.click('button.btn-primary:has-text("Sign in")', { force: true }).catch(async () => {
    console.log("btn-primary sign-in click failed, trying generic submit");
    await page.click('button[type="submit"]', { force: true });
  });
  await page.waitForLoadState("networkidle", { timeout: 30000 }).catch(() => {});
  console.log("post-login URL:", page.url());
  await dismissInterstitials(page);

  console.log("=== DASHBOARD ===");
  await page.goto(BASE + "/dashboard", { waitUntil: "networkidle", timeout: 30000 });
  await dismissInterstitials(page);
  console.log("dashboard title:", await page.title());
  await page.screenshot({ path: "/tmp/recon-dashboard.png", fullPage: true });

  console.log("=== DEPLOY WIZARD ===");
  await page.goto(BASE + "/dashboard/deploy", { waitUntil: "networkidle", timeout: 30000 });
  await dismissInterstitials(page);
  await page.screenshot({ path: "/tmp/recon-deploy-1.png", fullPage: true });
  const buttons1 = await page.locator("button, a[role=button], [role=option], [data-service]").allTextContents();
  console.log("deploy step1 clickable texts:", JSON.stringify(buttons1.map((t) => t.trim()).filter(Boolean)));
  const html1 = await page.content();
  console.log("deploy step1 HTML length:", html1.length);
  require("fs").writeFileSync("/tmp/recon-deploy-1.html", html1);

  await browser.close();
};

run().catch((e) => {
  console.error("FATAL", e);
  process.exit(1);
});

