import { chromium } from "playwright";
import { writeFileSync } from "node:fs";

const BASE = "https://staging.nxeon.cloud";

const dumpInteractive = async (page, label) => {
  const els = await page.locator("button, a, [role=button], [role=option], input[type=radio], label").all();
  const out = [];
  for (const el of els) {
    const txt = (await el.textContent().catch(() => "") || "").trim().replace(/\s+/g, " ");
    const cls = await el.getAttribute("class").catch(() => "");
    const dt = await el.getAttribute("data-testid").catch(() => "");
    if (txt || dt) out.push({ txt: txt.slice(0, 60), dt, cls: (cls || "").slice(0, 60) });
  }
  writeFileSync(`/tmp/dump-${label}.json`, JSON.stringify(out, null, 1));
  console.log(`--- ${label}: ${out.length} interactive elements, dumped to /tmp/dump-${label}.json ---`);
  console.log(out.slice(0, 40).map((o) => `[${o.txt}]`).join(" "));
};

const run = async () => {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  await ctx.addCookies([{ name: "nxeon_cookie_consent", value: "necessary", domain: "staging.nxeon.cloud", path: "/" }]);
  const page = await ctx.newPage();

  await page.goto(BASE + "/login", { waitUntil: "networkidle" });
  await page.fill("#login-email", "demo@nxeon.cloud");
  await page.fill("#login-password", "NxeonDemo!2026");
  await Promise.all([
    page.waitForNavigation({ timeout: 10000 }),
    page.locator('button:has-text("Sign in")').first().click({ force: true }),
  ]);
  await page.waitForTimeout(1000);
  await ctx.storageState({ path: "/tmp/nxeon-demo-storage.json" });
  console.log("logged in, storage state saved");

  await page.goto(BASE + "/dashboard/deploy", { waitUntil: "networkidle" });
  await page.waitForTimeout(1500);
  await page.screenshot({ path: "/tmp/deploy-step1.png", fullPage: true });
  await dumpInteractive(page, "deploy-step1");

  // Try clicking something that looks like "VPS" to advance
  const vpsCandidates = ["VPS", "Cloud VPS", "Deploy a VPS", "Virtual Private Server"];
  let clicked = null;
  for (const t of vpsCandidates) {
    const loc = page.locator(`text=${t}`).first();
    if (await loc.count()) {
      try {
        await loc.click({ force: true, timeout: 2000 });
        clicked = t;
        break;
      } catch {}
    }
  }
  console.log("clicked VPS candidate:", clicked);
  await page.waitForTimeout(1200);
  await page.screenshot({ path: "/tmp/deploy-step2.png", fullPage: true });
  await dumpInteractive(page, "deploy-step2");

  await browser.close();
};
run().catch((e) => { console.error(e); process.exit(1); });

