import { chromium } from "playwright";
import { mkdirSync } from "node:fs";

const BASE = "https://staging.nxeon.cloud";
const OUT = "/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/nxeon-demo-screens";
mkdirSync(OUT, { recursive: true });

const WEB01_ID = "cmsrjypgk0004hl3wtghpmo82";
const MC_SURVIVAL_ID = "cmsrjypgr000ahl3wkda5bbtw";

async function dismissInterstitials(page) {
  const selectors = [
    'button:has-text("Skip")',
    'button:has-text("Got it")',
    'button:has-text("No thanks")',
    "button.promo-modal-close",
    "button.promo-bar-close",
    '[aria-label="Close"]',
    '[aria-label="Dismiss"]',
  ];
  for (let i = 0; i < 3; i++) {
    let clicked = false;
    for (const sel of selectors) {
      try {
        const loc = page.locator(sel).first();
        if (await loc.isVisible({ timeout: 400 }).catch(() => false)) {
          await loc.click({ force: true, timeout: 1500 }).catch(() => {});
          clicked = true;
          await page.waitForTimeout(250);
        }
      } catch {}
    }
    if (!clicked) break;
  }
}

async function shot(page, name) {
  await dismissInterstitials(page);
  await page.waitForLoadState("networkidle", { timeout: 15000 }).catch(() => {});
  await page.waitForTimeout(500);
  await page.screenshot({ path: `${OUT}/${name}.png`, fullPage: true });
  console.log("SHOT:", name);
}

async function footerButtonTexts(page) {
  const texts = await page.locator("button").allTextContents();
  return texts.map((t) => t.trim()).filter(Boolean);
}

const run = async () => {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  await ctx.addCookies([{ name: "nxeon_cookie_consent", value: "necessary", domain: "staging.nxeon.cloud", path: "/" }]);
  const page = await ctx.newPage();

  // --- login ---
  await page.goto(BASE + "/login", { waitUntil: "networkidle" });
  await dismissInterstitials(page);
  await page.fill("#login-email", "demo@nxeon.cloud");
  await page.fill("#login-password", "NxeonDemo!2026");
  await Promise.all([
    page.waitForNavigation({ timeout: 10000 }),
    page.locator('button:has-text("Sign in")').first().click({ force: true }),
  ]);
  await page.waitForTimeout(800);
  console.log("logged in, url:", page.url());

  // --- dashboard ---
  await page.goto(BASE + "/dashboard", { waitUntil: "networkidle" });
  await shot(page, "dashboard-overview");

  // --- VPS server detail ---
  await page.goto(BASE + `/dashboard/servers/${WEB01_ID}`, { waitUntil: "networkidle" });
  await shot(page, "vps-server-detail");

  // --- game server detail + mods tab ---
  await page.goto(BASE + `/dashboard/servers/${MC_SURVIVAL_ID}`, { waitUntil: "networkidle" });
  await shot(page, "gameserver-detail");
  await page.goto(BASE + `/dashboard/servers/${MC_SURVIVAL_ID}?tab=mods`, { waitUntil: "networkidle" });
  await shot(page, "gameserver-mods-tab");

  // --- VPS checkout wizard ---
  await page.goto(BASE + "/dashboard/deploy", { waitUntil: "networkidle" });
  await shot(page, "checkout-vps-step1-select-service");

  await page.getByText("VPS Servers", { exact: false }).first().click({ force: true });
  await page.waitForTimeout(1000);
  console.log("step2 footer buttons:", await footerButtonTexts(page));

  // select the cheapest plan: "Starter" -> its "Select plan" button is first in DOM order
  await page.locator('button:has-text("Select plan")').first().click({ force: true });
  await page.waitForTimeout(500);
  await shot(page, "checkout-vps-step2-configure");

  // advance: Next
  await page.locator('button:has-text("Next")').first().click({ force: true });
  await page.waitForTimeout(1000);
  console.log("step3 footer buttons:", await footerButtonTexts(page));
  await shot(page, "checkout-vps-step3-region");

  await page.locator('button:has-text("Next")').first().click({ force: true });
  await page.waitForTimeout(1000);
  console.log("step4 footer buttons:", await footerButtonTexts(page));
  await shot(page, "checkout-vps-step4-payment");

  // Try to advance to the final review/deploy step WITHOUT submitting yet, so we can screenshot it
  const btns4 = await footerButtonTexts(page);
  console.log("about to click a next-like button, options were:", btns4);
  await page.locator('button:has-text("Next")').first().click({ force: true }).catch(async () => {
    console.log("no 'Next' on payment step, trying Review/Deploy");
  });
  await page.waitForTimeout(1000);
  console.log("step5 footer buttons:", await footerButtonTexts(page));
  await shot(page, "checkout-vps-step5-review");

  await ctx.storageState({ path: "/tmp/nxeon-demo-storage.json" });
  console.log("PAUSE POINT — not submitting yet, inspect step5 screenshot before final submit.");
  await browser.close();
};
run().catch((e) => {
  console.error("FATAL", e);
  process.exit(1);
});

