import { chromium } from "playwright";
import { mkdirSync } from "node:fs";
import { execSync } from "node:child_process";

const BASE = "https://staging.nxeon.cloud";
const OUT = "/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/nxeon-demo-screens";
mkdirSync(OUT, { recursive: true });
const DEMO_USER_ID = "cmrzacelu0000hlb4e2yqw2vh";

async function dismissInterstitials(page) {
  const selectors = [
    'button:has-text("Skip")', 'button:has-text("Got it")', 'button:has-text("No thanks")',
    "button.promo-modal-close", "button.promo-bar-close", '[aria-label="Close"]', '[aria-label="Dismiss"]',
  ];
  for (let i = 0; i < 3; i++) {
    let clicked = false;
    for (const sel of selectors) {
      try {
        const loc = page.locator(sel).first();
        if (await loc.isVisible({ timeout: 400 }).catch(() => false)) {
          await loc.click({ force: true, timeout: 1500 }).catch(() => {});
          clicked = true;
          await page.waitForTimeout(250);
        }
      } catch {}
    }
    if (!clicked) break;
  }
}
async function shot(page, name) {
  await dismissInterstitials(page);
  await page.waitForLoadState("networkidle", { timeout: 12000 }).catch(() => {});
  await page.waitForTimeout(600);
  await page.screenshot({ path: `${OUT}/${name}.png`, fullPage: true });
  console.log("SHOT:", name);
}
async function clickAdvance(page, candidates) {
  for (const text of candidates) {
    const loc = page.locator(`button:has-text("${text}")`).first();
    const visible = await loc.isVisible({ timeout: 800 }).catch(() => false);
    if (!visible) continue;
    const disabled = await loc.isDisabled().catch(() => false);
    if (disabled) continue;
    await loc.click({ force: true });
    console.log("advanced via:", text);
    return text;
  }
  console.log("clickAdvance: NO candidate matched among", candidates);
  return null;
}
function newestServerIdForUser() {
  const out = execSync(
    `sudo -u postgres psql -d nxeon_staging -t -A -c "SELECT id FROM \\"Server\\" WHERE \\"userId\\"='${DEMO_USER_ID}' ORDER BY \\"createdAt\\" DESC LIMIT 1;"`
  ).toString().trim();
  return out;
}

const run = async () => {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, storageState: "/tmp/nxeon-demo-storage.json" });
  const page = await ctx.newPage();

  const before = newestServerIdForUser();
  console.log("newest server before game order:", before);

  await page.goto(BASE + "/dashboard/deploy", { waitUntil: "networkidle" });
  await dismissInterstitials(page);
  await page.getByText("Game Servers", { exact: false }).first().click({ force: true });
  await page.waitForTimeout(1200);
  await shot(page, "checkout-game-step2-select-game");

  await page.getByText("Minecraft", { exact: false }).first().click({ force: true });
  await page.waitForTimeout(1200);
  await shot(page, "checkout-game-step3-configure-size");
  console.log("size-step buttons:", (await page.locator("button").allTextContents()).map(t=>t.trim()).filter(Boolean));

  // pick the cheapest/first plan tier if "Select plan" buttons exist; else it may have auto-advanced already
  const selectPlanBtn = page.locator('button:has-text("Select plan")').first();
  if (await selectPlanBtn.isVisible({ timeout: 1500 }).catch(() => false)) {
    await selectPlanBtn.click({ force: true });
    await page.waitForTimeout(1200);
  }
  await shot(page, "checkout-game-step4-region-or-next");

  await clickAdvance(page, ["Next", "Pay", "Continue"]);
  await page.waitForTimeout(1200);

  const balanceToggle = page.locator("text=Use account balance").first();
  if (await balanceToggle.isVisible({ timeout: 2000 }).catch(() => false)) {
    await balanceToggle.click({ force: true }).catch(() => {});
    await page.waitForTimeout(800);
  }
  await shot(page, "checkout-game-step5-payment");

  const clicked = await clickAdvance(page, ["and deploy", "Complete deployment", "Pay", "Deploy"]);
  console.log("game pay click result:", clicked);

  // poll DB for the new server row rather than trusting client redirect
  let newId = null;
  for (let i = 0; i < 20; i++) {
    await page.waitForTimeout(500);
    const latest = newestServerIdForUser();
    if (latest && latest !== before) { newId = latest; break; }
  }
  console.log("new game server id:", newId);
  if (newId) {
    await page.goto(BASE + `/dashboard/servers/${newId}?purchase=1`, { waitUntil: "load" });
    await page.waitForTimeout(700);
    await page.screenshot({ path: `${OUT}/deploying-in-progress-game.png`, fullPage: true });
    console.log("SHOT: deploying-in-progress-game");
  }

  await browser.close();
};
run().catch((e) => { console.error("FATAL", e); process.exit(1); });

